	ptr = malloc(_size+16+1);
	diff= ((-(int)ptr - 1)&15) + 1;
	ptr = (void*)(((char*)ptr)+diff);
	((char*)ptr)[-1]= diff;
	return ptr;
#endif //MEMALIGN
